CREATE TABLE IF NOT EXISTS character_equipment(character_id BIGINT UNSIGNED NOT NULL,slot VARCHAR(32) NOT NULL,item VARCHAR(100) NOT NULL,metadata_json JSON NULL,PRIMARY KEY(character_id,slot),FOREIGN KEY(character_id) REFERENCES characters(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS inventory_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,character_id BIGINT UNSIGNED NOT NULL,action VARCHAR(32) NOT NULL,item VARCHAR(100) NULL,amount INT NOT NULL DEFAULT 0,details_json JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(character_id,created_at),FOREIGN KEY(character_id) REFERENCES characters(id) ON DELETE CASCADE);
